#include <bits/stdc++.h>
using namespace std;const int N=2564,D=15;short X[N][D];int ord[N],part;int8_t q[D];uint16_t B[12];long long seen=0,kept=0,hist[13]{};ofstream fo,fb;
void test(){seen++;int c=0;for(int t=0;t<N;t++){int i=ord[t],d=2*q[14]*X[i][14];for(int j=0;j<14;j++)if(q[j])d+=q[j]*X[i][j];if(d>14){if(c==12){c=13;break;}B[c++]=i;}}if(c<=12){hist[c]++;for(int j=c;j<12;j++)B[j]=65535;int16_t v[D];for(int j=0;j<D;j++)v[j]=q[j];fo.write((char*)v,sizeof(v));fb.write((char*)B,sizeof(B));kept++;if(c==0){cout<<"POTENTIAL free"<<endl;fo.flush();fb.flush();exit(0);}}if(seen%1000000==0)cout<<"seen "<<seen<<" kept "<<kept<<endl;}
void signs(int x,int y,vector<int>&p){for(int mask=0;mask<512;mask++){memset(q,0,sizeof(q));q[x]=3*((mask&1)?-1:1);q[y]=3*((mask&2)?-1:1);for(int j=0;j<6;j++)q[p[j]]=(mask>>(j+2)&1)?-2:2;q[14]=(mask&256)?-2:2;test();}}
void choose(int x,int y,int start,int k,vector<int>&p){if(k==0){signs(x,y,p);return;}for(int i=start;i<14;i++){if(i==x||i==y)continue;p.push_back(i);choose(x,y,i+1,k-1,p);p.pop_back();}}
int main(int argc,char**argv){part=atoi(argv[1]);string t=to_string(part);fo.open("radical50_Q"+t+".bin",ios::binary);fb.open("radical50_B"+t+".bin",ios::binary);ifstream f("source.bin",ios::binary);f.read((char*)X,sizeof(X));iota(ord,ord+N,0);mt19937 rng(151519);shuffle(ord,ord+N,rng);vector<int>p;for(int x=0;x<14;x++)if(x%2==part)for(int y=x+1;y<14;y++)choose(x,y,0,6,p);cout<<"done seen "<<seen<<" kept "<<kept<<" hist ";for(int i=0;i<=12;i++)cout<<i<<":"<<hist[i]<<" ";cout<<endl;}
